(114, 'React Native - My Doctor', 'Informatika', 'Project Aplikasi Mobile Android dengan React Native', 'BWA', '5. Instalasi dan Struktur Folder', '9. SETUP Project & Library', 'Tools :\n\nhttps://drive.google.com/drive/folders/1tEB3lpI3FB4UyKuCEuSGhzzBeHuEwIk3?usp=drive_link', 'https://drive.google.com/file/d/1n8N5ld_ysXHtDyZk9r-JkimHspUUtgMN/view?usp=drive_link', '0', '2025-08-29 01:34:11', '2025-08-29 01:34:11'),
(115, 'React Native - My Doctor', 'Informatika', 'Project Aplikasi Mobile Android dengan React Native', 'BWA', '1. Splash Page', '10. Slicing - Welcome Screen', 'Di bagian ini kita akan belajar slicing atau motongin desain jadi kode. Setiap menu di aplikasi bakal kita pecah dari desain template jadi komponen React Native yang hidup. Jadi nggak cuma liat gambar doang, tapi halaman Splash akan kita ubah menjasi kode.', 'https://drive.google.com/file/d/1ZHxIdZvS3mIgxq3PRoi8y-CYuO4gAdAu/view?usp=drive_link', '0', '2025-08-29 01:36:09', '2025-08-29 01:43:14'),
(116, 'React Native - My Doctor', 'Informatika', 'Project Aplikasi Mobile Android dengan React Native', 'BWA', '2. Get Started Page', '10. Slicing - Welcome Screen', 'Setiap menu di aplikasi bakal kita pecah dari desain template jadi komponen React Native yang hidup. Jadi nggak cuma liat gambar doang, tapi halaman Get Started akan kita ubah menjadi kode.', 'https://drive.google.com/file/d/1ZxFd10MeDYVe54Fip0AZDiVVIzRnnVbZ/view?usp=drive_link', '0', '2025-08-29 01:36:47', '2025-08-29 01:43:34'),
(117, 'React Native - My Doctor', 'Informatika', 'Project Aplikasi Mobile Android dengan React Native', 'BWA', '3. Instalasi Fonts di React Native', '10. Slicing - Welcome Screen', 'Bagaimana agar bisa menggunakan Fonts yang beragam di React Native. Simak tutorial ini dengan baik, kemudian praktekan.', 'https://drive.google.com/file/d/1splD4hSLwZ8a-Guu7nLYWMJt0xv9E444/view?usp=drive_link', '0', '2025-08-29 01:37:41', '2025-08-29 01:41:42'),
(118, 'React Native - My Doctor', 'Informatika', 'Project Aplikasi Mobile Android dengan React Native', 'BWA', '1. Routing di React Native', '11. Navigasi (Routing)', 'Di bagian ini kita bakal belajar routing alias pindah-pindah halaman. Jadi tiap menu yang udah kita slicing, sekarang bisa diklik buat masuk ke halaman lain. Dengan navigasi ini, aplikasi jadi beneran hidup—bisa lompat dari Home ke Profile, dari Task ke Detail, dan balik lagi dengan mulus.', 'https://drive.google.com/file/d/10tleAepOiafCKU1EWfJznEwlNwapXtWK/view?usp=drive_link', '0', '2025-08-29 02:26:18', '2025-08-29 02:40:12'),
(119, 'React Native - My Doctor', 'Informatika', 'Project Aplikasi Mobile Android dengan React Native', 'BWA', '2. Install and Setup Basic Routing', '11. Navigasi (Routing)', 'Di bagian ini kita bakal belajar routing alias pindah-pindah halaman. Jadi tiap menu yang udah kita slicing, sekarang bisa diklik buat masuk ke halaman lain. Dengan navigasi ini, aplikasi jadi beneran hidup—bisa lompat dari Home ke Profile, dari Task ke Detail, dan balik lagi dengan mulus.', 'https://drive.google.com/file/d/19Q1ZdR77ACuLiMeEWjclpahhgqgYtjfd/view?usp=drive_link', '0', '2025-08-29 02:27:02', '2025-08-29 02:40:04'),
(120, 'React Native - My Doctor', 'Informatika', 'Project Aplikasi Mobile Android dengan React Native', 'BWA', '3. Stack Navigator', '11. Navigasi (Routing)', 'Apa itu Stack Navigator? Di bagian ini kita bakal belajar routing alias pindah-pindah halaman. Jadi tiap menu yang udah kita slicing, sekarang bisa diklik buat masuk ke halaman lain. Dengan navigasi ini, aplikasi jadi beneran hidup—bisa lompat dari Home ke Profile, dari Task ke Detail, dan balik lagi dengan mulus.', 'https://drive.google.com/file/d/1d0-s5oTTylnGz6GCCEjaKoyjmq4Mz0b9/view?usp=drive_link', '0', '2025-08-29 02:27:37', '2025-08-29 02:39:50'),
(121, 'React Native - My Doctor', 'Informatika', 'Project Aplikasi Mobile Android dengan React Native', 'BWA', '4. Navigate vs Replace', '11. Navigasi (Routing)', 'Dalam React Native ada dua kode navigasi yang harus difahami perbedaan nya sebelum kamu memakai nya, yaitu NAGIVATE dan REPLACE Dengan navigasi ini, aplikasi jadi beneran hidup—bisa lompat dari Home ke Profile, dari Task ke Detail, dan balik lagi dengan mulus.', 'https://drive.google.com/file/d/1Fwfw3T1bQzVXSc9-UWu4bj09ENlM3gHI/view?usp=drive_link', '0', '2025-08-29 02:28:51', '2025-08-29 02:37:32');
INSERT INTO `academy_courses` (`id`, `name`, `subject`, `note`, `author`, `title`, `section`, `description`, `video_url`, `video_duration`, `created_at`, `updated_at`) VALUES
